/* Hidden attribute safeguard */
[hidden] {
  display: none !important;
}

:root {
  --color-bg: #14131a;
  --color-surface: #22202c;
  --color-surface-hover: #2b2838;
  --color-gold: #f4b41b;
  --color-accent: #3b82f6;
  --color-text: #f3f4f6;
  --color-muted: #9ca3af;
  --color-disabled: #4b4859;
  --border-radius: 12px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 1.5rem 1rem;
  background-color: var(--color-bg);
  color: var(--color-text);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  font-size: 16px;
  line-height: 1.5;
}

.miner-card {
  width: 100%;
  max-width: 420px;
  min-width: 280px;
  background-color: var(--color-surface);
  border-radius: var(--border-radius);
  padding: 1.75rem;
  box-shadow: 0 10px 25px rgba(0, 0, 0, 0.45);
  border: 1px solid rgba(255, 255, 255, 0.08);
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.card-header {
  text-align: center;
}

.game-title {
  font-size: 1.6rem;
  font-weight: 700;
  color: var(--color-gold);
  letter-spacing: 0.5px;
}

.game-subtitle {
  font-size: 1rem;
  color: var(--color-muted);
  margin-top: 0.25rem;
}

.scene-container {
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: #100f16;
  border-radius: 8px;
  padding: 0.5rem;
  border: 2px solid #2e2c3c;
}

#pixelCanvas {
  image-rendering: pixelated;
  width: 100%;
  max-width: 280px;
  height: auto;
  aspect-ratio: 4 / 3;
  display: block;
}

.stats-panel {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
}

.stat-box {
  background-color: #1a1824;
  border-radius: 8px;
  padding: 0.75rem 1rem;
  text-align: center;
  border: 1px solid rgba(255, 255, 255, 0.05);
}

.stat-label {
  display: block;
  font-size: 0.9rem;
  color: var(--color-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.stat-value {
  display: block;
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--color-gold);
  margin-top: 0.25rem;
}

.actions-panel {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.action-btn {
  appearance: none;
  border: none;
  cursor: pointer;
  background: var(--color-gold);
  color: #1a1400;
  padding: 0.85rem 1.25rem;
  border-radius: 8px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.2rem;
  font-family: inherit;
  font-weight: 600;
  transition: background-color 0.15s ease, transform 0.05s ease, opacity 0.15s ease;
}

.action-btn:hover:not(:disabled) {
  background-color: #f7c346;
}

.action-btn:active:not(:disabled) {
  transform: translateY(1px);
}

.action-btn:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

.action-btn:disabled {
  background-color: var(--color-disabled);
  color: #8c899c;
  cursor: not-allowed;
  opacity: 0.65;
}

.btn-title {
  font-size: 1.1rem;
  font-weight: 700;
}

.btn-subtitle {
  font-size: 0.85rem;
  font-weight: 500;
}

.inventory-info {
  text-align: center;
  font-size: 0.95rem;
  color: var(--color-muted);
}

.inventory-info strong {
  color: var(--color-text);
}

(function () {
  "use strict";

  // Game state
  let gold = 0;
  let drills = 0;
  const DRILL_COST = 10;
  const BASE_RATE = 1;

  // DOM references
  const goldDisplay = document.getElementById("goldDisplay");
  const rateDisplay = document.getElementById("rateDisplay");
  const buyDrillBtn = document.getElementById("buyDrillBtn");
  const drillsCount = document.getElementById("drillsCount");
  const canvas = document.getElementById("pixelCanvas");
  const ctx = canvas.getContext("2d");

  function getRate() {
    return BASE_RATE + drills;
  }

  function updateUI() {
    goldDisplay.textContent = gold;
    rateDisplay.textContent = `${getRate()}/s`;
    drillsCount.textContent = drills;
    buyDrillBtn.disabled = gold < DRILL_COST;
  }

  function buyDrill() {
    if (gold >= DRILL_COST) {
      gold -= DRILL_COST;
      drills += 1;
      updateUI();
    }
  }

  // Animation & Pixel graphics
  let frame = 0;
  function drawPixelArt() {
    ctx.imageSmoothingEnabled = false;
    // Clear canvas - dark cavern background
    ctx.fillStyle = "#15141c";
    ctx.fillRect(0, 0, 160, 120);

    // Cave ground
    ctx.fillStyle = "#2c2839";
    ctx.fillRect(0, 92, 160, 28);
    ctx.fillStyle = "#3d3950";
    ctx.fillRect(0, 90, 160, 2);

    // Gold vein on the right
    ctx.fillStyle = "#49435b";
    ctx.fillRect(124, 46, 36, 44);
    ctx.fillStyle = "#f4b41b";
    ctx.fillRect(130, 56, 8, 8);
    ctx.fillRect(142, 68, 10, 8);
    ctx.fillRect(132, 78, 12, 6);
    ctx.fillRect(148, 52, 6, 6);

    // Sparkle animation near gold ore
    if ((frame % 30) < 15) {
      ctx.fillStyle = "#ffffff";
      ctx.fillRect(138, 52, 2, 2);
      ctx.fillRect(144, 76, 2, 2);
    }

    // Pixel Miner Character (Centered-left)
    const bob = Math.floor(Math.sin(frame * 0.15) * 2);
    const mx = 64;
    const my = 58 + bob;

    // Hardhat (yellow)
    ctx.fillStyle = "#f4b41b";
    ctx.fillRect(mx + 2, my - 2, 12, 6);
    ctx.fillRect(mx, my + 2, 16, 2);
    // Face
    ctx.fillStyle = "#fcd4a1";
    ctx.fillRect(mx + 2, my + 4, 12, 8);
    // Eye
    ctx.fillStyle = "#1a1400";
    ctx.fillRect(mx + 10, my + 6, 2, 2);
    // Shirt (blue)
    ctx.fillStyle = "#3b82f6";
    ctx.fillRect(mx + 2, my + 12, 12, 10);
    // Pants (dark navy)
    ctx.fillStyle = "#1e293b";
    ctx.fillRect(mx + 3, my + 22, 10, 10);
    ctx.fillStyle = "#15141c";
    ctx.fillRect(mx + 7, my + 26, 2, 6);

    // Pickaxe swing animation
    const swing = (frame % 20) < 10;
    ctx.fillStyle = "#8d6e63"; // Handle
    if (swing) {
      ctx.fillRect(mx + 12, my + 10, 10, 3);
      ctx.fillStyle = "#94a3b8"; // Pick head
      ctx.fillRect(mx + 22, my + 6, 4, 11);
    } else {
      ctx.fillRect(mx + 12, my + 14, 8, 3);
      ctx.fillStyle = "#94a3b8";
      ctx.fillRect(mx + 18, my + 12, 4, 10);
    }

    // Active Drill graphic if drills > 0
    if (drills > 0) {
      const dx = 20;
      const dy = 74;
      const drillVibe = (frame % 6) < 3 ? 0 : 1;
      // Drill Body
      ctx.fillStyle = "#475569";
      ctx.fillRect(dx, dy + drillVibe, 16, 12);
      ctx.fillStyle = "#f4b41b";
      ctx.fillRect(dx + 2, dy + 2 + drillVibe, 12, 4);
      // Bit
      ctx.fillStyle = "#cbd5e1";
      ctx.fillRect(dx + 16, dy + 4 + drillVibe, 6, 4);
      ctx.fillRect(dx + 22, dy + 5 + drillVibe, 3, 2);
    }

    frame++;
    requestAnimationFrame(drawPixelArt);
  }

  // Event Listeners
  buyDrillBtn.addEventListener("click", buyDrill);

  // 1-second gold accumulation interval
  setInterval(function () {
    gold += getRate();
    updateUI();
  }, 1000);

  // Initial render
  updateUI();
  requestAnimationFrame(drawPixelArt);
})();
